/**
 * Records a durable log event
 */
export const createDurableJsonCollector = () => {
    const steps = [];
    const logLines = [];
    const activeSteps = new Map();
    function record(event) {
        if (event.kind === 'log') {
            const logLine = {
                level: event.level,
                message: event.message,
            };
            if (event.step === null) {
                logLines.push(logLine);
                return;
            }
            const step = activeSteps.get(event.step);
            if (step) {
                step.logs.push(logLine);
                return;
            }
            logLines.push(logLine);
            return;
        }
        if (event.phase === 'start') {
            const step = {
                ...event,
                logs: [],
            };
            steps.push(step);
            activeSteps.set(event.name, step);
            return;
        }
        const step = activeSteps.get(event.name);
        if (!step)
            return;
        step.phase = event.phase;
        step.durationMs = event.durationMs;
        if (event.phase === 'complete') {
            step.output = event.output;
        }
        if (event.phase === 'error') {
            step.error = event.error;
        }
        activeSteps.delete(event.name);
    }
    return {
        record,
        result: () => ({ steps, logs: logLines }),
    };
};
